<script setup>
import{ref,watch,onMounted,computed}from'vue';import{useRoute}from'vue-router';import{ElMessage}from'element-plus';import PageHeader from'../components/PageHeader.vue';import{queryEntity}from'../api/admin.js';const route=useRoute(),items=ref([]),keyword=ref(''),dialog=ref(false);const configs={customers:{description:'维护客户档案与联系进度',columns:[['id','客户编号',120],['name','客户姓名',120],['phone','联系电话',140],['city','所在城市',120],['count','需求数量',100],['lastContact','最近联系',120],['status','状态',100]]},designers:{description:'管理设计师专业方向与在办任务',columns:[['id','编号',90],['name','姓名',110],['specialty','专业方向',180],['tasks','在办任务',100],['phone','联系电话',140],['status','状态',100]]},users:{description:'管理系统账号、角色与启用状态',columns:[['account','账号',150],['name','姓名',120],['role','角色',140],['lastLogin','最近登录',180],['status','状态',100]]},products:{description:'维护客户端产品系列及发布状态',columns:[['id','编号',90],['name','产品名称',220],['category','分类',100],['style','风格',130],['material','主要材质',180],['updatedAt','更新时间',120],['status','状态',100]]},cases:{description:'维护真实案例内容及发布状态',columns:[['id','编号',90],['name','案例名称',220],['space','空间',100],['style','风格',130],['area','面积',100],['updatedAt','更新时间',120],['status','状态',100]]}};const cfg=computed(()=>configs[route.meta.entity]||configs.customers);async function load(){items.value=(await queryEntity(route.meta.entity,{keyword:keyword.value})).data.items}onMounted(load);watch(()=>route.meta.entity,()=>{keyword.value='';load()});function save(){dialog.value=false;ElMessage.success('静态数据已保存')}
</script>
<template><div class="admin-page"><PageHeader :title="$route.meta.title" :description="cfg.description"><el-button type="primary" @click="dialog=true">新增记录</el-button></PageHeader><div class="work-surface"><div class="filter-bar"><el-input v-model="keyword" placeholder="输入关键词搜索" clearable style="width:240px" @keyup.enter="load"/><el-button type="primary" plain @click="load">查询</el-button><el-button @click="keyword='';load()">重置</el-button><span style="margin-left:auto;color:var(--muted)">共 {{items.length}} 条</span></div><div class="table-wrap"><el-table :data="items"><el-table-column v-for="c in cfg.columns" :key="c[0]" :prop="c[0]" :label="c[1]" :min-width="c[2]"/><el-table-column label="操作" width="130" fixed="right"><template #default><el-button link type="primary" @click="dialog=true">编辑</el-button><el-button link>查看</el-button></template></el-table-column></el-table><div class="table-footer"><el-pagination background layout="prev,pager,next" :total="items.length" :page-size="10"/></div></div></div><el-dialog v-model="dialog" :title="`新增${$route.meta.title.replace('管理','')}`" width="580px"><el-form label-width="90px"><el-form-item label="名称"><el-input placeholder="请输入名称"/></el-form-item><el-form-item label="状态"><el-select model-value="启用"><el-option label="启用" value="启用"/><el-option label="停用" value="停用"/></el-select></el-form-item><el-form-item label="备注"><el-input type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
